const $=s=>document.querySelector(s),symbols=['◆','●','♣','✦','☾','♥'],colors=[['#fa9376','#9b343c'],['#75c6ed','#21518e'],['#8cdeb0','#247353'],['#f7db80','#a17030'],['#bd9de8','#5b3b88'],['#f7a7c9','#a54076']];
let board,hp,enemy,maxEnemy,stage,turn,total,best=0,combo,selected=-1,drag=false,moved=false,busy=false,start=0,ticker,epoch=0,ended=false;
try{best=Number(localStorage.getItem('orbquest-best'))||0}catch{}
const random=()=>Math.floor(Math.random()*6),sleep=ms=>new Promise(r=>setTimeout(r,ms));
function matches(b){const hit=new Set();for(let r=0;r<5;r++)for(let c=0;c<6;c++){let i=r*6+c,v=b[i];if(v==null)continue;if(c<4&&v===b[i+1]&&v===b[i+2]){let x=c;while(x<6&&b[r*6+x]===v)hit.add(r*6+x++)}if(r<3&&v===b[i+6]&&v===b[i+12]){let y=r;while(y<5&&b[y*6+c]===v)hit.add(y++*6+c)}}const groups=[];while(hit.size){let first=hit.values().next().value,q=[first],g=[];hit.delete(first);while(q.length){let i=q.pop();g.push(i);for(let j of [i%6>0?i-1:-1,i%6<5?i+1:-1,i-6,i+6])if(hit.has(j)&&b[j]===b[first]){hit.delete(j);q.push(j)}}groups.push(g)}return groups}
function fresh(){let b=[];for(let i=0;i<30;i++){let v;do{v=random()}while(i%6>1&&b[i-1]===v&&b[i-2]===v||i>=12&&b[i-6]===v&&b[i-12]===v);b.push(v)}return b}
function render(){ $('#board').innerHTML=board.map((v,i)=>`<button role="gridcell" aria-label="${['火','水','木','光','闇','回復'][v]} ${Math.floor(i/6)+1}行${i%6+1}列" class="orb ${i===selected?'selected':''}" data-i="${i}" style="--c:${colors[v][0]};--d:${colors[v][1]}">${symbols[v]}</button>`).join('');update()}
function update(){ $('#hp').textContent=`${hp.toLocaleString()} / 5,000`;$('#hpFill').style.width=hp/50+'%';$('#enemyHP').textContent='HP '+enemy.toLocaleString();$('#enemyFill').style.width=enemy/maxEnemy*100+'%';$('#stage').textContent=`BATTLE ${stage} / 5`;$('#stageText').textContent=`STAGE 0${stage} / 05`;$('#enemyTurn').textContent=`敵の攻撃まで ${turn} ターン`;$('#damage').textContent=total.toLocaleString();$('#combos').textContent=combo;$('#record').innerHTML=best+'<em> combo</em>';$('#best').textContent=best;document.querySelectorAll('.dots b').forEach((e,i)=>e.classList.toggle('active',i<stage));$('#enemyName').textContent=['翠晶のガーディアン','蒼月のガーディアン','金陽のガーディアン','紫夜のガーディアン','星霊王アストラ'][stage-1];$('.monster').style.filter=`hue-rotate(${(stage-1)*55}deg) drop-shadow(0 0 15px #7ce2bd30)`}
function message(t){$('#floatText').textContent=t;$('#floatText').style.opacity=1;setTimeout(()=>$('#floatText').style.opacity=0,1500)}
function reset(){epoch++;clearInterval(ticker);board=fresh();hp=5000;stage=1;maxEnemy=enemy=3000;turn=2;total=combo=0;selected=-1;busy=drag=moved=ended=false;$('#status').textContent='ドロップを動かして冒険をはじめよう';$('#timer').textContent='8.0 s';$('#timeFill').style.width='100%';render()}
function begin(i){if(busy||ended)return;selected=i;drag=true;moved=false;render();$('#status').textContent='なぞってドロップを入れ替えよう'}
function move(i){if(!drag||busy||i===selected||i<0||i>=30)return;const a=selected;if(Math.abs(a%6-i%6)+Math.abs(Math.floor(a/6)-Math.floor(i/6))!==1)return;if(!moved){moved=true;start=performance.now();ticker=setInterval(()=>{let left=Math.max(0,8-(performance.now()-start)/1000);$('#timer').textContent=left.toFixed(1)+' s';$('#timeFill').style.width=left/8*100+'%';if(left===0)finish()},40)}[board[a],board[i]]=[board[i],board[a]];selected=i;render()}
async function finish(){if(!drag)return;drag=false;clearInterval(ticker);selected=-1;if(!moved){render();return}busy=true;combo=0;render();const current=epoch;let attack=0,heal=0;for(let cascade=0;cascade<40;cascade++){const groups=matches(board);if(!groups.length)break;for(const group of groups){combo++;let type=board[group[0]];if(type===5)heal+=group.length*220;else attack+=group.length*150;for(const i of group)$('#board').children[i].classList.add('clear');$('#combos').textContent=combo;message(combo+' COMBO');await sleep(260);if(current!==epoch)return}const cleared=new Set(groups.flat());for(let c=0;c<6;c++){let kept=[];for(let r=4;r>=0;r--)if(!cleared.has(r*6+c))kept.push(board[r*6+c]);for(let r=4;r>=0;r--)board[r*6+c]=kept[4-r]??random()}render();await sleep(250);if(current!==epoch)return}
const dealt=Math.round(attack*(1+Math.max(0,combo-1)*.25));enemy=Math.max(0,enemy-dealt);hp=Math.min(5000,hp+heal);total+=dealt;if(combo>best){best=combo;try{localStorage.setItem('orbquest-best',best)}catch{}}$('#status').textContent=combo?`${combo}コンボ！ ${dealt.toLocaleString()} ダメージ${heal?' / HP回復':''}`:'そろわなかった… 次の一手でつなごう';update();if(enemy===0){message('STAGE CLEAR!');await sleep(1200);if(current!==epoch)return;if(stage===5){ended=true;message('ALL CLEAR!');$('#status').textContent='全ステージクリア！「はじめから」で再挑戦';busy=false;return}stage++;maxEnemy=enemy=2400+stage*1000;turn=2;hp=Math.min(5000,hp+700);update()}else{turn--;if(turn===0){let damage=650+stage*150;hp=Math.max(0,hp-damage);message('−'+damage+' HP');turn=2}update();if(hp===0){ended=true;$('#status').textContent='冒険終了。「はじめから」で再挑戦しよう';message('TRY AGAIN')}}busy=false;$('#timer').textContent='8.0 s';$('#timeFill').style.width='100%'}
$('#board').addEventListener('pointerdown',e=>{let el=e.target.closest('[data-i]');if(!el)return;e.preventDefault();begin(+el.dataset.i)});window.addEventListener('pointermove',e=>{if(!drag)return;e.preventDefault();let el=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-i]');if(el)move(+el.dataset.i)},{passive:false});window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',finish);window.addEventListener('blur',finish);$('#board').addEventListener('keydown',e=>{let el=e.target.closest('[data-i]');if(!el)return;let i=+el.dataset.i;if(e.key==='Enter'||e.key===' '){e.preventDefault();drag?finish():begin(i)}if(drag&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();let next=selected+({ArrowLeft:-1,ArrowRight:1,ArrowUp:-6,ArrowDown:6}[e.key]);move(next);$('#board').children[selected]?.focus()}});$('#reset').onclick=reset;$('#help').onclick=()=>$('#dialog').showModal();$('#close').onclick=()=>$('#dialog').close();reset();
